/**
 * Return how a person set OpenBot up for themselves, on every device they sign in from, with the default for anything they never chose. Only the person themselves may read them.
 * @summary Read a person's preferences
 */

export const getPreferencesPathPersonIdMax = 200;

export const getPreferencesPathPersonIdRegExp = new RegExp("\\S");

export const GetPreferencesParams = zod.object({
  organizationId: zod
    .string()
    .min(1)
    .describe(
      "The organization. Until multi-organization lands every install has one, addressed as `default`.",
    ),
  personId: zod
    .string()
    .min(1)
    .max(getPreferencesPathPersonIdMax)
    .regex(getPreferencesPathPersonIdRegExp)
    .describe(
      "The person: me for the caller, or a person's id. A person's own things (their instructions, preferences, API keys, sessions and linked accounts) answer only the person themselves, by either.",
    ),
});

export const GetPreferencesResponse = zod
  .object({
    messageListEmphasis: zod
      .enum(["agent", "thread"])
      .describe(
        "What the conversation list leads with, the Bot or the conversation.",
      ),
    selfHostBannerDismissed: zod
      .boolean()
      .describe(
        "Whether they closed the banner offering help self-hosting OpenBot.",
      ),
    narration: zod
      .union([zod.enum(["on", "off"]), zod.null()])
      .describe(
        "Whether they narrate their recordings in OpenBot's browser, which opens the microphone only when on. Null until they choose, which the browser asks before their first recording.",
      ),
    skin: zod
      .enum(["openbot", "openduet", "opendots", "openfuse"])
      .describe(
        "How OpenBot looks. openbot is OpenBot as it is without a skin.",
      ),
    proactive: zod
      .enum(["on", "off"])
      .describe(
        "Whether their Bots check in on their behalf at all. off stops every Bot's check-ins, whatever each Bot's own setting says.",
      ),
    starterTourChannelId: zod
      .string()
      .optional()
      .describe(
        "The conversation the starter tour is offered in, set by the server when the person starts their first one. Absent until then.",
      ),
  })
  .describe(
    "How a person set OpenBot up for themselves, on every device they sign in from.",
  );

